import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"OCSE：9 步安装向导与 OCSECL 命令字典","description":"","frontmatter":{},"headers":[],"relativePath":"zh/components/ocse/ocse-wizard.md","filePath":"zh/components/ocse/ocse-wizard.md"}'),r={name:"zh/components/ocse/ocse-wizard.md"};function l(a,t,s,n,i,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="ocse-9-步安装向导与-ocsecl-命令字典" tabindex="-1">OCSE：9 步安装向导与 OCSECL 命令字典 <a class="header-anchor" href="#ocse-9-步安装向导与-ocsecl-命令字典" aria-label="Permalink to &quot;OCSE：9 步安装向导与 OCSECL 命令字典&quot;">​</a></h1><p>安装器为<strong>同一个</strong>命令面提供两扇门：图形向导（默认）与 OCSECL shell。向导<strong>自身不实现任何安装逻辑</strong>——它执行的每一个变更动作 都是一条真实的 OCSECL 命令行，经 <code>ocse_cl_exec</code> 运行，与 shell 执行的完全一致。命令失败时，错误页会显示捕获的输出，并提供 Retry/Back。</p><h2 id="九个步骤" tabindex="-1">九个步骤 <a class="header-anchor" href="#九个步骤" aria-label="Permalink to &quot;九个步骤&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>页面</th><th>内容</th></tr></thead><tbody><tr><td>1</td><td>欢迎 + 语言</td><td>选择语言（英文 / 简体中文）；整个 UI 包括向导在内实时跟随切换</td></tr><tr><td>2</td><td>目标磁盘</td><td><code>lsdisk</code> 列出可安装目标；已能启动 <code>opencube.elf</code> 的磁盘被拒绝（既有系统检查）</td></tr><tr><td>3</td><td>分区</td><td><code>lspart &lt;disk&gt;</code> 列出分区与空闲间隙；向导预选<strong>最大空闲间隙</strong>并构建 <code>mkpart &lt;disk&gt; &lt;startMiB&gt; &lt;endMiB&gt;</code>；高级选项可删除分区（<code>rmpart ... confirm</code>）</td></tr><tr><td>4</td><td>格式化</td><td><code>mkfs.fat32 &lt;device&gt; confirm</code>——FAT32 是 OCBL 引导分区契约；页面说明格式化仅销毁该分区上的数据</td></tr><tr><td>5</td><td>用户账户</td><td>名字、全名与口令；口令在<strong>离开页面前</strong>即散列为 64 位十六进制 SHA-256——之后写入的记录是 <code>name:full:sha256</code>，绝不是明文口令</td></tr><tr><td>6</td><td>系统配置</td><td>主机名、语言、更新 URL、自动更新检查</td></tr><tr><td>7</td><td>确认</td><td>上述全部内容一屏汇总，此时尚未写入任何东西</td></tr><tr><td>8</td><td>安装</td><td>逐阶段执行真实命令序列（见下）</td></tr><tr><td>9</td><td>完成</td><td>结束或重启进入已安装的系统</td></tr></tbody></table><h2 id="第-8-步-六个安装阶段" tabindex="-1">第 8 步：六个安装阶段 <a class="header-anchor" href="#第-8-步-六个安装阶段" aria-label="Permalink to &quot;第 8 步：六个安装阶段&quot;">​</a></h2><p>每个阶段都是一条真实命令行；进度条按阶段推进，首次失败即跳转 错误页，携带失败命令与其捕获输出。</p><table tabindex="0"><thead><tr><th>阶段</th><th>构建的命令</th><th>说明</th></tr></thead><tbody><tr><td>1. 挂载</td><td><code>mount &lt;device&gt; /mnt</code></td><td>此前失败重试残留的挂载先被丢弃（<code>umount /mnt</code>）再重试一次挂载</td></tr><tr><td>2. 安装</td><td><code>install &lt;disk&gt; &lt;n&gt; confirm</code></td><td>完整安装状态机：介质检查、恢复分区划分、载荷解包、引导代码、引导标志</td></tr><tr><td>3. 配置</td><td><code>config set hostname &lt;h&gt;</code>，随后 <code>config set lang &lt;en|zh&gt;</code>、可选 <code>config set update_url &lt;u&gt;</code>、<code>config set auto_check &lt;0|1&gt;</code></td><td>写入已安装配置的四个键</td></tr><tr><td>4. 用户记录</td><td><code>write /mnt/etc/users &lt;name&gt;:&lt;full&gt;:&lt;sha256&gt;</code></td><td>SHA-256 口令散列；装不下的记录被拒绝，绝不截断</td></tr><tr><td>5. 同步</td><td><code>sync</code></td><td>刷块缓存</td></tr><tr><td>6. 卸载</td><td><code>umount /mnt</code></td><td>目标保持干净</td></tr></tbody></table><h2 id="ocsecl-命令字典-40-条" tabindex="-1">OCSECL 命令字典（40 条） <a class="header-anchor" href="#ocsecl-命令字典-40-条" aria-label="Permalink to &quot;OCSECL 命令字典（40 条）&quot;">​</a></h2><p>shell 随时可从面板（热键）与串行控制台进入。<code>help</code> 列出全部； <code>help &lt;cmd&gt;</code> 显示单条命令。</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>help</code></td><td>显示全部命令或某条命令的帮助</td></tr><tr><td><code>lsdisk</code></td><td>列出可安装目标磁盘</td></tr><tr><td><code>lspart &lt;disk&gt;</code></td><td>列出某盘的分区</td></tr><tr><td><code>parted &lt;disk&gt;</code></td><td>显示原始分区表</td></tr><tr><td><code>mkpart &lt;disk&gt; &lt;startMiB&gt; &lt;endMiB&gt;</code></td><td>创建分区</td></tr><tr><td><code>rmpart &lt;disk&gt; &lt;n&gt; confirm</code></td><td>删除 #n 分区（需 <code>confirm</code>）</td></tr><tr><td><code>setflag &lt;disk&gt; &lt;n&gt; boot [on\\|off]</code></td><td>设置分区标志</td></tr><tr><td><code>mkfs.fat32 &lt;device&gt; confirm</code></td><td>格式化为 FAT32（销毁数据；需 <code>confirm</code>）</td></tr><tr><td><code>mkfs.exfat &lt;device&gt; confirm</code></td><td>格式化为 exFAT（销毁数据；需 <code>confirm</code>）</td></tr><tr><td><code>mkfs.ext4 &lt;device&gt; confirm</code></td><td>格式化为 ext4（销毁数据；需 <code>confirm</code>）</td></tr><tr><td><code>mount &lt;device&gt; &lt;path&gt;</code></td><td>挂载（文件系统自动识别）</td></tr><tr><td><code>umount &lt;path&gt;</code></td><td>卸载 path 处的文件系统</td></tr><tr><td><code>ls [path]</code></td><td>列目录</td></tr><tr><td><code>cd [path]</code></td><td>切换目录（默认 <code>/</code>）</td></tr><tr><td><code>pwd</code></td><td>显示当前目录</td></tr><tr><td><code>cat &lt;file&gt;</code></td><td>打印文本文件</td></tr><tr><td><code>write &lt;file&gt; [text ...]</code></td><td>写入一行</td></tr><tr><td><code>touch &lt;file&gt;</code></td><td>创建空文件</td></tr><tr><td><code>cp &lt;src&gt; &lt;dst&gt;</code></td><td>复制文件</td></tr><tr><td><code>mv &lt;src&gt; &lt;dst&gt;</code></td><td>移动或重命名文件</td></tr><tr><td><code>rm &lt;file&gt;</code></td><td>删除文件</td></tr><tr><td><code>mkdir &lt;path&gt;</code></td><td>创建目录</td></tr><tr><td><code>rmdir &lt;path&gt;</code></td><td>删除空目录</td></tr><tr><td><code>tar -t &lt;arc&gt;</code> / <code>tar -x &lt;arc&gt; [dir]</code></td><td>ustar 列出 / 解包</td></tr><tr><td><code>dd if= of= [bs= count= skip= seek=] [confirm]</code></td><td>块复制</td></tr><tr><td><code>sha256sum &lt;file&gt;</code> / <code>&lt;dev&gt; &lt;sectors&gt;</code></td><td>文件或磁盘区段的 SHA-256 摘要</td></tr><tr><td><code>install &lt;disk&gt; &lt;n&gt; confirm</code></td><td>把 OCOS 安装到某分区</td></tr><tr><td><code>ocbl-install &lt;disk&gt; confirm</code></td><td>写入 OCBL 引导代码</td></tr><tr><td><code>config [set &lt;k&gt; &lt;v&gt;]</code></td><td>显示/编辑已安装配置</td></tr><tr><td><code>sync</code></td><td>把块缓存刷入磁盘</td></tr><tr><td><code>reboot</code></td><td>刷盘并重启</td></tr><tr><td><code>shutdown</code></td><td>刷盘并关机</td></tr><tr><td><code>hwcheck</code></td><td>重新运行四项硬件检查</td></tr><tr><td><code>disks</code></td><td>原始磁盘清单</td></tr><tr><td><code>lang [en\\|zh]</code></td><td>显示或设置语言</td></tr><tr><td><code>serial_encoding [utf8\\|gbk]</code></td><td>显示/设置串行线路编码</td></tr><tr><td><code>clear</code></td><td>清屏</td></tr><tr><td><code>click &lt;x&gt; &lt;y&gt;</code></td><td>探测 GUI 按钮几何（诊断用）</td></tr><tr><td><code>gui</code></td><td>切回图形面板</td></tr><tr><td><code>halt</code></td><td>停机（不走 ACPI 路径）</td></tr></tbody></table><p>下一篇：<a href="./ocse-recovery.html">安装失败与恢复</a>。</p>',11)])])}const f=d(r,[["render",l]]);export{m as __pageData,f as default};
